'use strict';
(()=>{
 const entry=document.querySelector('[data-page="entry"]'),assets=document.querySelector('[data-page="assets"]');entry.setAttribute('aria-label','记录与更新');assets.setAttribute('aria-label','账户与资产');
 const accountPanel=$('accountForm').closest('article');accountPanel.id='accountSetup';assets.prepend(accountPanel);
 const welcome=document.createElement('article');welcome.id='onboardingPanel';welcome.hidden=true;welcome.innerHTML='<p id="onboardingStatus"></p>';document.querySelector('[data-page="overview"]').prepend(welcome);
 const header=document.createElement('article');header.className='panel flexible-entry-header';header.innerHTML='<div class="panel-head"><div><h2>随时记录，保存即更新</h2><p>收入按发生日期记录，资产按盘点日期更新；不用等待月末，也无需关账。</p></div><a class="text-action" href="#overview">查看家庭总览 ↗</a></div>';
 const tabs=document.createElement('div');tabs.className='entry-tabs';tabs.setAttribute('role','tablist');tabs.setAttribute('aria-label','选择录入内容');tabs.innerHTML='<button type="button" role="tab" data-entry-view="flows">收入与转账</button><button type="button" role="tab" data-entry-view="balances">更新余额与估值</button>';
 const panes={};for(const key of ['flows','balances']){const p=document.createElement('div');p.id='monthPane-'+key;p.className='month-pane';p.setAttribute('role','tabpanel');panes[key]=p;}
 const manual=$('manualForm').closest('article');manual.querySelector('h2').textContent='记录收入与转账';panes.flows.append(manual);panes.flows.classList.add('month-flow-grid');
 const balances=document.createElement('article');balances.className='panel';balances.id='balanceUpdatePanel';balances.innerHTML='<div class="panel-head"><div><h2>更新账户余额与持仓估值</h2><p>选实际盘点日期，只填这次要更新的账户，空白项保持原样；不要求一次填齐。</p></div><a class="text-action" href="#assets">管理账户 ↗</a></div><form id="balanceUpdatesForm"><div class="balance-topbar"><label class="field">实际盘点日期<input id="balanceUpdateDate" type="date" required></label><p id="balanceUpdateDateNote" class="muted"></p></div><div class="auto-fx-notice"><div><strong>汇率自动填写</strong><p id="balanceFxStatus"></p></div><button type="button" class="outline" id="refreshBalanceRates">更新汇率</button></div><div id="balanceUpdateFields" class="month-balance-grid"></div><div class="form-actions"><button class="solid" id="saveBalanceUpdates" type="submit">保存本次更新</button></div></form><p id="balanceUpdateResult" role="status"></p>';panes.balances.append(balances);
 const more=document.createElement('details');more.className='panel other-entry';more.innerHTML='<summary>其他录入方式 · 粘贴助手整理结果</summary>';for(const child of [...entry.children])more.append(child);entry.replaceChildren(header,tabs,panes.flows,panes.balances,more);
 const extras=document.createElement('details');extras.className='full';extras.innerHTML='<summary>更多选项 · 发生时间和备注</summary>';$('manualForm').append(extras);extras.append($('recordTime').parentElement,$('recordMemo').parentElement);[...$('recordKind').options].find(o=>o.value==='balance')?.remove();
 document.querySelector('[data-route="entry"] span').textContent='记录与更新';document.querySelector('[data-route="assets"] span').textContent='账户与资产';pageInfo.entry=['记录与更新','每一次变化，随手记下。','收入随时记，资产随时更新，保存后自动汇总。'];pageInfo.assets=['账户与资产','账户与资产','统一管理家庭的现金、存款与投资。'];
 const oldFamily=$('aiProvider').closest('.two-cols')?.querySelector('article');if(oldFamily&&!oldFamily.contains($('aiProvider')))oldFamily.remove();
 let first=true,fxState=null,balanceKey='',busy=false,pending=null;
 function showView(view){if(!panes[view])view='flows';for(const [key,pane]of Object.entries(panes))pane.hidden=key!==view;for(const b of tabs.querySelectorAll('button')){const selected=b.dataset.entryView===view;b.classList.toggle('active',selected);b.setAttribute('aria-selected',String(selected));b.setAttribute('aria-controls','monthPane-'+b.dataset.entryView);}}
 tabs.querySelectorAll('button').forEach(b=>b.onclick=()=>showView(b.dataset.entryView));showView('flows');
 function renderFx(){const q=fxState?.quote;for(const p of $('balanceUpdateFields').querySelectorAll('[data-fx-currency]')){const c=p.dataset.fxCurrency,rate=q?.toCny?.[c];p.textContent=rate?`1 ${c} ≈ ${rate.toLocaleString('zh-CN',{maximumFractionDigits:6})} CNY · ${q.rateDate} · ${q.source}${fxState.status==='stale'?'（缓存）':''}`:'暂未取得 '+c+' 汇率，请稍后更新。';p.classList.toggle('fx-unavailable',!rate);}$('balanceFxStatus').textContent=q?`最新可用参考日 ${q.rateDate} · ${q.source}${fxState.status==='stale'?' · 使用缓存':''}。保存后固定本次参考值。`:'外币余额自动获取最新可用参考汇率；无法获取时不会按0或1折算。';}
 async function loadFx(force=false){try{fxState=await api(force?'/api/fx/refresh':'/api/fx',force?{}:undefined);renderFx();}catch(e){$('balanceFxStatus').textContent=e.message;}}
 function draw(){if(!D.live)return;const date=$('balanceUpdateDate'),asOf=date.value||D.today;date.max=D.today;const typed=balanceKey===asOf?new Map([...$('balanceUpdateFields').querySelectorAll('[data-account]')].map(i=>[i.dataset.account,i.value])):new Map();balanceKey=asOf;$('balanceUpdateDateNote').textContent='按 '+asOf+' 保存实际金额；之后的新流水继续更新余额。';$('balanceUpdateFields').replaceChildren();
 const rank=a=>{const i=FamilyAccountCatalog.types.indexOf(FamilyChoices.displayType(a));return i<0?999:i;};const accounts=FamilyAccountCatalog.sorted(D.accounts.filter(a=>!a.archivedAt&&(!a.startDate||a.startDate<=asOf)),D.memberProfiles||[]).sort((a,b)=>rank(a)-rank(b)||FamilyChoices.displayType(a).localeCompare(FamilyChoices.displayType(b),'zh-CN'));let previous=null;
 for(const a of accounts){const type=FamilyChoices.displayType(a);if(type!==previous){const h=document.createElement('h3');h.className='balance-type-heading';h.textContent=type;$('balanceUpdateFields').append(h);previous=type;}const saved=D.records.filter(r=>r.type==='balance'&&r.account===a.id&&r.date===asOf).at(-1),book=D.balances.find(b=>b.id===a.id),wrap=document.createElement('div');wrap.className='monthly-account';const title=document.createElement('div');title.className='balance-account-title';const strong=document.createElement('strong'),small=document.createElement('small');strong.textContent=a.name;small.textContent=[memberName(a.owner),a.institution,a.currency].filter(Boolean).join(' · ');title.append(strong,small);const label=document.createElement('label');label.className='field';label.textContent='实际余额 / 总市值（'+a.currency+'）';const input=document.createElement('input');input.type='number';input.min='0';input.step='0.01';input.dataset.account=a.id;input.placeholder=saved?'已保存 '+(saved.cents/100).toFixed(2)+'，可更正':book?.nativeCents!==null&&book?.nativeCents!==undefined?'当前账面 '+(book.nativeCents/100).toFixed(2):'填写实际金额';input.value=typed.get(a.id)||'';label.append(input);wrap.append(title,label);if(a.currency!=='CNY'){const p=document.createElement('p');p.className='auto-fx-value';p.dataset.fxCurrency=a.currency;wrap.append(p);}$('balanceUpdateFields').append(wrap);}
 if(!accounts.length){const p=document.createElement('p');p.className='muted';p.textContent='所选日期还没有可更新的账户，请先建立账户或选择其纳入日期之后的日期。';$('balanceUpdateFields').append(p);}$('saveBalanceUpdates').disabled=busy||!accounts.length;renderFx();}
 $('balanceUpdateDate').value=D.today;$('balanceUpdateDate').max=D.today;$('balanceUpdateDate').onchange=()=>{pending=null;$('balanceUpdateResult').textContent='';draw();};$('refreshBalanceRates').onclick=async()=>{$('refreshBalanceRates').disabled=true;try{await loadFx(true);}finally{$('refreshBalanceRates').disabled=false;}};
 $('balanceUpdatesForm').onsubmit=async e=>{e.preventDefault();if(busy)return;const values=[...$('balanceUpdateFields').querySelectorAll('[data-account]')].filter(i=>i.value!=='').map(i=>({account:i.dataset.account,amount:i.value}));if(!values.length){$('balanceUpdateResult').textContent='请至少填写一个账户的实际金额。';return;}const body={date:$('balanceUpdateDate').value,balances:values},signature=JSON.stringify(body);if(!pending||pending.signature!==signature)pending={signature,body:{...body,requestId:FamilyClient.newId(),time:body.date===D.today?new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).format(new Date()):'23:59:59'}};busy=true;$('saveBalanceUpdates').disabled=true;try{const r=await api('/api/balances',pending.body);pending=null;balanceKey='';await refreshLedger();$('balanceUpdateResult').textContent=r.alreadyImported?'这次更新已保存，没有重复记账。':'已保存本次实际余额，未填写账户保持原样；总览和资产曲线已更新。';}catch(e){$('balanceUpdateResult').textContent=e.message;}finally{busy=false;draw();}};
 window.FamilyEntry={showView,reload:draw};function onData(){if(!D.live)return;$('onboardingStatus').textContent='已建立 '+D.accounts.length+' 个账户。';if(first){first=false;$('balanceUpdateDate').value=D.today;if(!D.accounts.length)location.hash='#assets';loadFx();}draw();}document.addEventListener('family-ledger-ready',onData);if(D.live)onData();route();
})();
